import { useState } from 'react';
import { Avatar, Badge, Button, Cell, DataTable, Metric, Modal, Panel, SearchInput, Select } from '../ui';
import { ATTENDANCE } from '../../data/mockData';
import { useStore } from '../../hooks/useStore';
import { downloadCsv } from '../../lib/download';

/** Looks like a QR code; a real one would be generated by the server for the open session. */
function QrPreview({ seed }) {
  const n = 21;
  const cells = [];
  let h = [...seed].reduce((a, c) => (a * 31 + c.charCodeAt(0)) >>> 0, 7);
  for (let y = 0; y < n; y++) for (let x = 0; x < n; x++) {
    const finder = (x < 7 && y < 7) || (x >= n - 7 && y < 7) || (x < 7 && y >= n - 7);
    h = (h * 1103515245 + 12345) >>> 0;
    const edge = (a, b) => a === 0 || a === 6 || b === 0 || b === 6;
    const on = finder
      ? (() => { const fx = x % (n - 7 + 0) < 7 ? x : x - (n - 7); const fy = y < 7 ? y : y - (n - 7); return edge(fx, fy) || (fx >= 2 && fx <= 4 && fy >= 2 && fy <= 4); })()
      : (h >> 16) % 2 === 0;
    if (on) cells.push(<rect key={`${x}-${y}`} x={x} y={y} width="1" height="1" />);
  }
  return <svg viewBox={`-1 -1 ${n + 2} ${n + 2}`} className="mx-auto h-48 w-48 rounded-2xl bg-white p-2 text-ink-950" fill="currentColor" shapeRendering="crispEdges" role="img" aria-label="Session QR code">{cells}</svg>;
}

const POINTS = [
  { key: 'amIn',  label: 'AM check-in',  period: 'AM' },
  { key: 'amOut', label: 'AM check-out', period: 'AM' },
  { key: 'pmIn',  label: 'PM check-in',  period: 'PM' },
  { key: 'pmOut', label: 'PM check-out', period: 'PM' },
];
const STATUSES = ['Checked in', 'Checked out', 'Not yet', 'Pending sync'];

/** One check point: the status, with the time it was recorded underneath. */
function Point({ cell }) {
  return (
    <div>
      <Badge value={cell.status} />
      <small className="mt-0.5 block pl-3.5 text-[11px] tabular-nums text-ink-500">{cell.time || '—'}</small>
    </div>
  );
}

/**
 * AttendanceTab — attendance lives inside the activity (it is per activity).
 * Each day has four check points: AM check-in, AM check-out, PM check-in and PM check-out.
 */
export default function AttendanceTab({ activity, notify }) {
  const { staffDays } = useStore();
  const [day, setDay] = useState(staffDays[0]?.n ?? 1);
  const [session, setSession] = useState('All sessions');
  const [status, setStatus] = useState('All statuses');
  const [query, setQuery] = useState('');
  const [qr, setQr] = useState(false);

  const live = activity.status === 'Ongoing' || activity.status === 'Upcoming';
  const shown = POINTS.filter((p) => session === 'All sessions' || session === `${p.period} only`);

  const rows = ATTENDANCE.filter((p) => {
    if (!p.name.toLowerCase().includes(query.toLowerCase())) return false;
    if (status !== 'All statuses' && !shown.some((pt) => p[pt.key].status === status)) return false;
    return true;
  });

  const count = (key) => ATTENDANCE.filter((p) => p[key].status === (key.endsWith('In') ? 'Checked in' : 'Checked out')).length;
  const registered = ATTENDANCE.length;
  const pending = ATTENDANCE.reduce((n, p) => n + POINTS.filter((pt) => p[pt.key].status === 'Pending sync').length, 0);
  const pct = (n) => `${Math.round((n / registered) * 100)}% of registered`;

  const columns = [
    { key: 'name', label: 'Participant', render: (p) => <div className="flex items-center gap-3"><Avatar name={p.name} size="sm" /><Cell title={p.name} sub={p.agency} /></div> },
    ...shown.map((pt) => ({ key: pt.key, label: pt.label, render: (p) => <Point cell={p[pt.key]} /> })),
  ];

  const exportCsv = () => {
    downloadCsv(`attendance-${activity.id}-day-${day}.csv`, [
      ['Participant', 'Organization', ...POINTS.flatMap((p) => [p.label, `${p.label} time`])],
      ...rows.map((p) => [p.name, p.agency, ...POINTS.flatMap((pt) => [p[pt.key].status, p[pt.key].time])]),
    ]);
    notify?.('Attendance exported as CSV');
  };

  return (
    <div className="space-y-4">
      <div className="flex flex-wrap items-center justify-between gap-3">
        <div>
          <h2 className="text-sm font-medium text-ink-950">Attendance monitoring</h2>
          <p className="text-xs text-ink-500">Participants scan in and out twice a day: morning and afternoon.</p>
        </div>
        <div className="flex flex-wrap gap-2">
          <Button variant="secondary" size="sm" icon="download" onClick={exportCsv}>Export attendance</Button>
          <Button size="sm" icon="scan" onClick={() => setQr(true)}>Show QR code</Button>
        </div>
      </div>

      <div className="grid grid-cols-2 gap-4 xl:grid-cols-5">
        <Metric label="Registered" value={registered} note="Total participants" />
        {POINTS.map((pt) => <Metric key={pt.key} label={pt.label} value={count(pt.key)} note={pct(count(pt.key))} tone="brand" />)}
      </div>

      <Panel pad={false} className="overflow-hidden">
        <div className="flex flex-wrap items-center gap-3 p-4">
          <SearchInput value={query} onChange={setQuery} placeholder="Search participant…" className="w-full sm:w-64" />
          <Select value={day} onChange={(e) => setDay(Number(e.target.value))} aria-label="Day">
            {staffDays.map((d) => <option key={d.n} value={d.n}>Day {d.n} · {d.label.split(',')[0]}</option>)}
          </Select>
          <Select value={session} onChange={(e) => setSession(e.target.value)} aria-label="Session">
            <option>All sessions</option><option>AM only</option><option>PM only</option>
          </Select>
          <Select value={status} onChange={(e) => setStatus(e.target.value)} aria-label="Status">
            <option>All statuses</option>{STATUSES.map((s) => <option key={s}>{s}</option>)}
          </Select>
          <span className="ml-auto flex items-center gap-2 text-xs text-ink-500">
            <i className={`h-1.5 w-1.5 rounded-full ${live ? 'animate-pulse bg-emerald-400' : 'bg-ink-400'}`} />
            {live ? 'Live sync active' : 'Check-in is closed'}{pending > 0 && ` · ${pending} pending sync`}
          </span>
        </div>
        <DataTable columns={columns} rows={rows} empty="No participants match these filters." />
      </Panel>

      {qr && <QrModal activity={activity} day={day} onClose={() => setQr(false)} />}
    </div>
  );
}

/** One QR code per check point, so a participant cannot check out with the check-in code. */
function QrModal({ activity, day, onClose }) {
  const [point, setPoint] = useState(POINTS[0]);
  return (
    <Modal title="Attendance QR code" subtitle={`${activity.title} · Day ${day}`} onClose={onClose} width={440}
      footer={<><span /><Button onClick={onClose}>Done</Button></>}>
      <div className="pb-2 text-center">
        <div role="tablist" aria-label="Check point" className="glass-inset mb-4 inline-flex flex-wrap justify-center rounded-full p-0.5">
          {POINTS.map((pt) => (
            <button key={pt.key} role="tab" aria-selected={point.key === pt.key} onClick={() => setPoint(pt)}
              className={`rounded-full px-3 py-1.5 text-xs transition-colors ${point.key === pt.key ? 'bg-white font-medium text-ink-950 shadow-sm' : 'text-ink-500 hover:text-ink-950'}`}>{pt.label}</button>
          ))}
        </div>
        <QrPreview seed={`${activity.id}-${day}-${point.key}`} />
        <p className="mt-3 text-xs text-ink-500">Participants scan this with the UniFyle app to record their {point.label.toLowerCase()}. It only works while that window is open.</p>
      </div>
    </Modal>
  );
}
